  function final(tit, txt, alvo, pagina) { return H.final(tit, txt, alvo, pagina) }
  function goS(r) { return function () { if (aqui() === P.admin && window.SHADM && (!window.__simSh2 || __simSh2.rota !== r)) SHADM.ir(r) } }
  function goW(r) { return function () { if (aqui() === P.woo && window.WOOADM && (!window.__simWoo || __simWoo.rota !== r)) WOOADM.ir(r) } }
