  /* quem volta um passo (ou recarrega) encontra a tela como estava: os passos refazem o estado de que precisam */
  function wooSet(patch) { return function () { var s = SITE.get(), mudou = false; for (var k in patch) if (JSON.stringify(s.woo[k]) !== JSON.stringify(patch[k])) { s.woo[k] = patch[k]; mudou = true } if (mudou) SITE.set(s) } }
