      var s0 = SITE.get(), pe = s0.shopify.prods.filter(function (x) { return x.id === 3 })[0]; if (pe && pe.fb) { pe.fb = false; SITE.set(s0) }   // quem voltou: a Ecobag ainda não foi incluída
      goS('produtos')(); if (!window.SHADM || aqui() !== P.admin) return;
